WITH parsed AS (SELECT id, service, status_code, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs) SELECT CASE WHEN duration_sec >= 3.4 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, SUM(status_code) FILTER (WHERE service = 'billing') AS billing_total_status_code, APPROX_PERCENTILE(status_code, 0.5) AS status_code_p50, COUNT(*) AS row_count, SIZE(COLLECT_SET(service)) AS num_services, COUNT_IF(tier = 'free') AS free_events FROM parsed GROUP BY CUBE (CASE WHEN duration_sec >= 3.4 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(*) < 1000 ORDER BY row_count ASC
